example_code:
stanje = 5000
iznos = int(input("Koliko želiš da podigneš? "))

if iznos > 0:
    if iznos <= stanje:
        stanje = stanje - iznos
        print(f"Isplaćeno {iznos} din. Novo stanje: {stanje} din.")
    else:
        print("Nemaš dovoljno novca na računu.")
else:
    print("Iznos mora biti veći od nule.")

